import os
import sys
import mmap
from multiprocessing import Pool

def _worker(args):
    fd, start, end = args
    mm = mmap.mmap(fd, 0, access=mmap.ACCESS_READ)
    sums = {}
    pos = start
    find = mm.find
    while pos < end:
        c1 = find(b',', pos)
        c2 = find(b',', c1 + 1)
        nl = find(b'\n', c2 + 1)
        if nl == -1:
            nl = end
        cat = mm[c1 + 1:c2]
        val = float(mm[c2 + 1:nl])
        try:
            sums[cat] += val
        except KeyError:
            sums[cat] = val
        pos = nl + 1
    mm.close()
    return sums

def main():
    fd = sys.stdin.fileno()
    try:
        size = os.fstat(fd).st_size
    except OSError:
        size = 0
    if size > 1_000_000:
        mm = mmap.mmap(fd, 0, access=mmap.ACCESS_READ)
        start = mm.find(b'\n') + 1
        n_workers = 8
        step = (size - start) // n_workers
        chunks = []
        cur = start
        for i in range(n_workers):
            nxt = size if i == n_workers - 1 else mm.find(b'\n', start + (i + 1) * step) + 1
            if nxt <= cur:
                continue
            chunks.append((fd, cur, nxt))
            cur = nxt
        mm.close()
        with Pool(n_workers) as pool:
            parts = pool.map(_worker, chunks)
        sums = {}
        for p in parts:
            for k, v in p.items():
                sums[k] = sums.get(k, 0.0) + v
    else:
        stdin = sys.stdin.buffer
        stdin.readline()
        sums = {}
