    out.write(b''.join(cat + b',' + f'{sums[cat]:.2f}\n'.encode('ascii') for cat in sorted(sums)))

if __name__ == '__main__':
    main()

import os
import sys
import ctypes
import subprocess

C_SRC = r"""
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char *key;
    int len;
    double sum;
    int used;
} Entry;

#define HT_SIZE 16384
static Entry table[HT_SIZE];

static inline unsigned int hash_bytes(const char *s, int len) {
    unsigned int h = 2166136261u;
    for (int i = 0; i < len; i++) {
        h = (h ^ (unsigned char)s[i]) * 16777619u;
    }
    return h;
}

static int cmp_entry(const void *a, const void *b) {
    const Entry *ea = *(const Entry **)a;
    const Entry *eb = *(const Entry **)b;
    int m = ea->len < eb->len ? ea->len : eb->len;
    int c = memcmp(ea->key, eb->key, m);
    if (c != 0) return c;
    return ea->len - eb->len;
}

int run_csvsum(int fd) {
    struct stat st;
    if (fstat(fd, &st) != 0 || st.st_size <= 0) return -1;
    size_t size = (size_t)st.st_size;
    const char *data = (const char *)mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) return -1;

    memset(table, 0, sizeof(table));
    const char *p = data;
    const char *end = data + size;

    while (p < end && *p != '\n') p++;
    if (p < end) p++;

    while (p < end) {
        while (p < end && *p != ',') p++;
        if (p >= end) break;
        p++;
        const char *cat_start = p;
        while (p < end && *p != ',') p++;
        int cat_len = (int)(p - cat_start);
        if (p >= end) break;
        p++;

        // fast float parse
        double sign = 1.0;
        if (*p == '-') { sign = -1.0; p++; }
        long long int_part = 0;
        while (p < end && *p >= '0' && *p <= '9') {
            int_part = int_part * 10 + (*p - '0');
            p++;
        }
        double val = (double)int_part;
        if (p < end && *p == '.') {
            p++;
            long long frac_part = 0;
            double div = 1.0;
            while (p < end && *p >= '0' && *p <= '9') {
                frac_part = frac_part * 10 + (*p - '0');
                div *= 10.0;
                p++;
            }
            val += frac_part / div;
        }
        val *= sign;
        while (p < end && *p != '\n') p++;
        if (p < end) p++;

        unsigned int idx = hash_bytes(cat_start, cat_len) & (HT_SIZE - 1);
        while (table[idx].used) {
            if (table[idx].len == cat_len && memcmp(table[idx].key, cat_start, cat_len) == 0) {
                table[idx].sum += val;
                goto next_row;
            }
            idx = (idx + 1) & (HT_SIZE - 1);
        }
        table[idx].used = 1;
        table[idx].len = cat_len;
        table[idx].key = (char *)malloc(cat_len + 1);
        memcpy(table[idx].key, cat_start, cat_len);
        table[idx].key[cat_len] = '\0';
        table[idx].sum = val;
    next_row:;
    }

    Entry *list[HT_SIZE];
    int count = 0;
    for (int i = 0; i < HT_SIZE; i++) {
        if (table[i].used) list[count++] = &table[i];
    }
    qsort(list, count, sizeof(Entry *), cmp_entry);

    for (int i = 0; i < count; i++) {
        printf("%s,%.2f\n", list[i]->key, list[i]->sum);
        free(list[i]->key);
    }
    fflush(stdout);
    munmap((void *)data, size);
    return 0;
}
"""

def main():
    so_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_csvsum_v1.so")
    if not os.path.exists(so_path):
        c_path = so_path + ".c"
        with open(c_path, "w") as f:
            f.write(C_SRC)
        subprocess.run(["clang", "-O3", "-shared", "-fPIC", c_path, "-o", so_path], check=True)
    lib = ctypes.CDLL(so_path)
    if lib.run_csvsum(sys.stdin.fileno()) == 0:
        return
    # Fallback for non-seekable pipes
    stdin = sys.stdin.buffer
    stdin.readline()
    sums = {}
    for line in stdin:
        _, cat, val = line.split(b',')
        sums[cat] = sums.get(cat, 0.0) + float(val)
    out = sys.stdout.buffer
    for cat in sorted(sums):
        out.write(cat + b',' + f'{sums[cat]:.2f}\n'.encode('ascii'))

if __name__ == '__main__':
    main()

import os
import sys
import ctypes
import subprocess

C_SRC = r"""
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    char *key;
    int len;
    double sum;
    int used;
} Entry;

#define HT_SIZE 4096

typedef struct {
    const char *start;
    const char *end;
    Entry table[HT_SIZE];
} WorkerArg;

static inline unsigned int hash_bytes(const char *s, int len) {
    unsigned int h = 2166136261u;
    for (int i = 0; i < len; i++) {
        h = (h ^ (unsigned char)s[i]) * 16777619u;
    }
    return h;
}

static void *worker_fn(void *arg) {
    WorkerArg *w = (WorkerArg *)arg;
    memset(w->table, 0, sizeof(w->table));
    const char *p = w->start;
    const char *end = w->end;

    while (p < end) {
        const char *c1 = (const char *)memchr(p, ',', end - p);
        if (!c1) break;
        const char *cat_start = c1 + 1;
        const char *c2 = (const char *)memchr(cat_start, ',', end - cat_start);
        if (!c2) break;
        int cat_len = (int)(c2 - cat_start);
        p = c2 + 1;

        double sign = 1.0;
        if (*p == '-') { sign = -1.0; p++; }
        long long int_part = 0;
        while (p < end && *p >= '0' && *p <= '9') {
            int_part = int_part * 10 + (*p - '0');
            p++;
        }
        double val = (double)int_part;
        if (p < end && *p == '.') {
            p++;
            long long frac_part = 0;
            double div = 1.0;
            while (p < end && *p >= '0' && *p <= '9') {
                frac_part = frac_part * 10 + (*p - '0');
                div *= 10.0;
                p++;
            }
            val += frac_part / div;
        }
        val *= sign;
        while (p < end && *p != '\n') p++;
        if (p < end) p++;

        unsigned int idx = hash_bytes(cat_start, cat_len) & (HT_SIZE - 1);
        while (w->table[idx].used) {
            if (w->table[idx].len == cat_len && memcmp(w->table[idx].key, cat_start, cat_len) == 0) {
                w->table[idx].sum += val;
                goto next_row;
            }
            idx = (idx + 1) & (HT_SIZE - 1);
        }
        w->table[idx].used = 1;
        w->table[idx].len = cat_len;
        w->table[idx].key = (char *)cat_start;
        w->table[idx].sum = val;
    next_row:;
    }
    return NULL;
}

static int cmp_entry(const void *a, const void *b) {
    const Entry *ea = *(const Entry **)a;
    const Entry *eb = *(const Entry **)b;
    int m = ea->len < eb->len ? ea->len : eb->len;
    int c = memcmp(ea->key, eb->key, m);
    if (c != 0) return c;
    return ea->len - eb->len;
}

int run_csvsum_mt(int fd) {
    struct stat st;
    if (fstat(fd, &st) != 0 || st.st_size <= 0) return -1;
    size_t size = (size_t)st.st_size;
    const char *data = (const char *)mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) return -1;

    const char *p = data;
    const char *end = data + size;
    while (p < end && *p != '\n') p++;
    if (p < end) p++;

    int nthreads = 8;
    pthread_t threads[8];
    WorkerArg *args = (WorkerArg *)calloc(nthreads, sizeof(WorkerArg));
    size_t rem = end - p;
    const char *cur = p;
    for (int t = 0; t < nthreads; t++) {
        args[t].start = cur;
        if (t == nthreads - 1) {
            args[t].end = end;
        } else {
            const char *target = p + (rem * (t + 1)) / nthreads;
            while (target < end && *target != '\n') target++;
            if (target < end) target++;
            args[t].end = target;
            cur = target;
        }
        pthread_create(&threads[t], NULL, worker_fn, &args[t]);
    }

    Entry global_table[HT_SIZE];
    memset(global_table, 0, sizeof(global_table));

    for (int t = 0; t < nthreads; t++) {
        pthread_join(threads[t], NULL);
        for (int i = 0; i < HT_SIZE; i++) {
            if (!args[t].table[i].used) continue;
            const char *k = args[t].table[i].key;
            int klen = args[t].table[i].len;
            double s = args[t].table[i].sum;
            unsigned int idx = hash_bytes(k, klen) & (HT_SIZE - 1);
            while (global_table[idx].used) {
                if (global_table[idx].len == klen && memcmp(global_table[idx].key, k, klen) == 0) {
                    global_table[idx].sum += s;
                    goto merged;
                }
                idx = (idx + 1) & (HT_SIZE - 1);
            }
            global_table[idx].used = 1;
            global_table[idx].len = klen;
            global_table[idx].key = (char *)k;
            global_table[idx].sum = s;
        merged:;
        }
    }

    Entry *list[HT_SIZE];
    int count = 0;
    for (int i = 0; i < HT_SIZE; i++) {
        if (global_table[i].used) list[count++] = &global_table[i];
    }
    qsort(list, count, sizeof(Entry *), cmp_entry);

    for (int i = 0; i < count; i++) {
        printf("%.*s,%.2f\n", list[i]->len, list[i]->key, list[i]->sum);
    }
    fflush(stdout);
    free(args);
    munmap((void *)data, size);
    return 0;
}
"""

def main():
    so_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_csvsum_mt.so")
    if not os.path.exists(so_path):
        c_path = so_path + ".c"
        with open(c_path, "w") as f:
            f.write(C_SRC)
        subprocess.run(["clang", "-O3", "-shared", "-fPIC", c_path, "-o", so_path], check=True)
    lib = ctypes.CDLL(so_path)
    if lib.run_csvsum_mt(sys.stdin.fileno()) == 0:
        return
    stdin = sys.stdin.buffer
    stdin.readline()
    sums = {}
    for line in stdin:
        _, cat, val = line.split(b',')
        sums[cat] = sums.get(cat, 0.0) + float(val)
    out = sys.stdout.buffer
    for cat in sorted(sums):
        out.write(cat + b',' + f'{sums[cat]:.2f}\n'.encode('ascii'))

if __name__ == '__main__':
    main()
